DECLARE d public.combat_v2_declarations%ROWTYPE; b clan_hoki_private.body_states%ROWTYPE;
  target uuid; native jsonb; outcome jsonb; result jsonb:='[]'::jsonb; facts jsonb;
  other_actor uuid; key text; reason text; unit integer; digest text; reaction text; source_knocked_out boolean;
BEGIN
  SELECT * INTO STRICT d FROM public.combat_v2_declarations WHERE id=p_declaration;
  IF d.kind<>'attacco' OR d.sanitized_intent#>>'{server_ability,source}' IS DISTINCT FROM 'mano' THEN RETURN result; END IF;
  IF NOT EXISTS(SELECT 1 FROM clan_hoki_private.body_states b0 WHERE b0.actor_id IN(d.actor_id,d.target_actor_id)
    AND b0.ended_at IS NULL) THEN RETURN result; END IF;
  native:=combat_effects_private.native_outcome(d.id,p_attack_target);
  target:=(native->>'target_actor_id')::uuid;
  outcome:=native->'outcome';
  digest:=public.combat_v2_sha256(native);
  IF native->>'state' IS DISTINCT FROM 'risolta' OR outcome->'success' IS DISTINCT FROM 'true'::jsonb
    OR coalesce((outcome->>'threshold_margin')::numeric,-1)<0 OR coalesce((outcome->>'damage_applied')::integer,0)<=0
    OR target IS DISTINCT FROM d.target_actor_id
    OR outcome @? '$.**.copy_intercepted ? (@ == true)'
    OR outcome @? '$.**.source_lost ? (@ == true)'
    OR outcome @? '$.**.striscio ? (@ == true)'
    OR coalesce(outcome->'raw','{}'::jsonb) ?| ARRAY['sabaku_armor','hyuga_rotation','aburame_clone']
  THEN RETURN result; END IF;
  IF p_attack_target IS NOT NULL THEN
    SELECT x.sanitized_intent->>'reaction' INTO reaction FROM public.combat_v2_defense_coverages dc
      JOIN public.combat_v2_declarations x ON x.id=dc.defense_declaration_id
      WHERE dc.attack_target_id=p_attack_target AND dc.mode='self';
    IF EXISTS(SELECT 1 FROM public.combat_v2_defense_coverages dc WHERE dc.attack_target_id=p_attack_target AND dc.mode<>'self')
    THEN RETURN result; END IF;
  ELSE
    SELECT x.sanitized_intent->>'reaction' INTO reaction FROM public.combat_v2_declarations x
      WHERE x.parent_attack_id=d.id AND x.kind='difesa';
  END IF;
  IF reaction IN ('tecnica','sostituzione','copie') THEN RETURN result; END IF;

  FOR b IN SELECT * FROM clan_hoki_private.body_states
    WHERE actor_id IN(d.actor_id,target) AND ended_at IS NULL ORDER BY actor_id FOR UPDATE LOOP
    key:='body-contact:'||d.id::text||':'||b.activation_id::text;
    SELECT e.facts INTO facts FROM clan_hoki_private.combat_events e WHERE e.event_key=key;
    IF FOUND THEN
      IF facts->>'outcome_sha256' IS DISTINCT FROM digest THEN RAISE EXCEPTION 'hoki_body_contact_conflict'; END IF;
      result:=result||jsonb_build_array(facts);
      CONTINUE;
    END IF;
    IF b.latest_contact_round=d.round_id OR b.spent_units>=5 THEN CONTINUE; END IF;
    source_knocked_out:=b.actor_id=target AND outcome->'ko'='true'::jsonb
      AND outcome->>'target_hp_after'='0'
      AND EXISTS(SELECT 1 FROM public.combat_v2_actors a
        JOIN public.combat_v2_rounds rr ON rr.id=d.round_id AND rr.session_id=a.session_id
        WHERE a.id=b.actor_id AND a.session_id=b.session_id AND a.state='fuori'
          AND a.mechanics_snapshot->>'vita'='0');
    IF source_knocked_out IS DISTINCT FROM true
      AND NOT EXISTS(SELECT 1 FROM public.combat_v2_actors a WHERE a.id=b.actor_id AND a.state='attivo')
    THEN PERFORM clan_hoki_private.body_stop(b.actor_id,'actor_inoperative'); CONTINUE; END IF;
    -- The armature must not be between either of the two bodies and the contact.
    IF EXISTS(SELECT 1 FROM clan_sabaku_private.armor_states x WHERE x.actor_id IN(d.actor_id,target) AND x.active)
    THEN
      IF source_knocked_out IS TRUE THEN PERFORM clan_hoki_private.body_stop(b.actor_id,'actor_inoperative'); END IF;
      CONTINUE;
    END IF;
    other_actor:=CASE WHEN b.actor_id=d.actor_id THEN target ELSE d.actor_id END;
    reason:=clan_hoki_private.apply_poison(d.id,p_attack_target,b.actor_id,other_actor,native);
    IF reason='applied' THEN
      unit:=b.spent_units+1;
      PERFORM clan_hoki_private.transition(b.owner_id,b.scope_id,b.scope_kind,'execute',b.activation_id,20+unit,
        b.kg,b.resistance,clock_timestamp(),true,0,clan_hoki_private.body_unit(b.activation_id,unit));
      UPDATE clan_hoki_private.body_states SET spent_units=unit,latest_contact_round=d.round_id WHERE activation_id=b.activation_id;
      IF unit=5 AND source_knocked_out IS DISTINCT FROM true THEN
        PERFORM clan_hoki_private.body_stop(b.actor_id,'spent');
      END IF;
    END IF;
    IF source_knocked_out IS TRUE THEN PERFORM clan_hoki_private.body_stop(b.actor_id,'actor_inoperative'); END IF;
    facts:=jsonb_build_object('version','hoki-body/1','source_actor_id',b.actor_id,'target_actor_id',other_actor,
      'poison_applied',reason='applied','reason',reason,'outcome_sha256',digest);
    INSERT INTO clan_hoki_private.combat_events(event_key,session_id,actor_id,round_id,kind,facts)
    VALUES(key,b.session_id,b.actor_id,d.round_id,'body_contact',facts);
    result:=result||jsonb_build_array(facts);
  END LOOP;
  RETURN result;
END

DECLARE a public.combat_v2_actors%ROWTYPE; c public.characters%ROWTYPE;
  g clan_hoki_private.release_gate%ROWTYPE; profile jsonb; staff_mark jsonb;
  candidate_scope text; kg integer; resistance integer;
BEGIN
  SELECT * INTO g FROM clan_hoki_private.release_gate WHERE technique_id=p_technique;
  IF NOT FOUND OR NOT (g.staff_enabled OR g.public_enabled) THEN RETURN NULL; END IF;
  SELECT * INTO a FROM public.combat_v2_actors WHERE id=p_actor AND actor_kind='pg'
    AND companion_id IS NULL AND state='attivo';
  IF NOT FOUND THEN RETURN NULL; END IF;
  SELECT * INTO c FROM public.characters WHERE id=a.character_id AND user_id=a.controller_user;
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF g.staff_enabled AND a.mechanics_snapshot#>>'{innata_staff_profile,profile_key}'='hoki-l1' THEN
    candidate_scope:='simulation';
    IF clan_hoki_private.session_kind(a.session_id) IS DISTINCT FROM candidate_scope THEN RETURN NULL; END IF;
    profile:=clan_innata_narrative_private.staff_profile_actor_v1(a.id);
    staff_mark:=coalesce(a.mechanics_snapshot->'hoki_staff_profile',
      a.mechanics_snapshot->'genin_trio_staff_profile');
    IF profile->>'profile_key' IS DISTINCT FROM 'hoki-l1'
      OR a.character_id NOT IN (
        '2a877f02-4993-4e65-9172-7d29f08c5b86'::uuid,
        '6bceee99-974f-426b-8d92-38b43b4a4267'::uuid)
      OR staff_mark->>'profile_key' IS DISTINCT FROM 'hoki-l1'
      OR staff_mark->>'context_id' IS DISTINCT FROM profile->>'context_id'
      OR jsonb_typeof(staff_mark->'techniques') IS DISTINCT FROM 'array'
      OR (staff_mark->'techniques' ? p_technique::text) IS DISTINCT FROM true
      OR a.mechanics_snapshot->>'resistenza' IS NULL OR a.mechanics_snapshot->>'resistenza' !~ '^[0-9]{1,9}$'
    THEN RETURN NULL; END IF;
    kg:=(profile->>'required_kg')::integer;
    resistance:=(a.mechanics_snapshot->>'resistenza')::integer;
  ELSIF g.public_enabled AND c.clan='Dokugan' AND c.kekkei_genkai>=30
    AND public._grade_rank(c.rank)>=public._grade_rank('Genin') THEN
    candidate_scope:='persistent';
    IF clan_hoki_private.session_kind(a.session_id) IS DISTINCT FROM candidate_scope OR NOT EXISTS(
      SELECT 1 FROM public.character_abilities ca WHERE ca.character_id=c.id AND ca.state='attiva'
        AND ca.technique_id IN ('ed808bc6-57f6-4853-80bf-9e6985ca0cc3',
          '41254b82-5b5e-46e9-9820-b3d604bbe38f','2fb9e210-225d-460a-a9f9-39ee64f8fce1',
          'ab64415a-cca3-472f-9203-84ad60c09405'))
      OR NOT EXISTS(SELECT 1 FROM public.character_abilities ca WHERE ca.character_id=c.id
        AND ca.technique_id=p_technique AND ca.state='attiva')
    THEN RETURN NULL; END IF;
    kg:=c.kekkei_genkai;
    resistance:=c.resistenza;
  ELSE
    RETURN NULL;
  END IF;
  IF kg IS NULL OR kg<30 OR resistance IS NULL OR resistance<0
    OR NOT EXISTS(SELECT 1 FROM public.clan_techniques ct WHERE ct.id=p_technique AND ct.is_active)
  THEN RETURN NULL; END IF;
  RETURN jsonb_build_object('session_id',a.session_id,'owner',c.id,
    'scope',CASE WHEN candidate_scope='simulation' THEN a.session_id ELSE c.id END,
    'kind',candidate_scope,'kg',kg,'resistance',resistance);
END

DECLARE a public.combat_v2_actors%ROWTYPE; t public.combat_v2_actors%ROWTYPE; c jsonb;
BEGIN
  SELECT * INTO STRICT a FROM public.combat_v2_actors WHERE id=p_source_actor;
  SELECT * INTO STRICT t FROM public.combat_v2_actors WHERE id=p_target_actor AND session_id=a.session_id FOR UPDATE;
  IF a.id=t.id OR (a.character_id IS NOT NULL AND a.character_id=t.character_id) THEN RETURN 'own_source_immune'; END IF;
  IF a.team_key=t.team_key OR t.state<>'attivo' OR t.companion_id IS NOT NULL THEN RETURN 'target_ineligible'; END IF;
  IF EXISTS (SELECT 1 FROM clan_hoki_private.minor_poison WHERE session_id=a.session_id
    AND target_actor_id=t.id AND remaining_turns>0) THEN RETURN 'already_poisoned'; END IF;
  c:=combat_effects_private.personal_turn(t.session_id,t.id);
  INSERT INTO clan_hoki_private.minor_poison(session_id,source_actor_id,target_actor_id,
    declaration_id,attack_target_id,outcome_sha256,exclude_turn_id)
  VALUES(a.session_id,a.id,t.id,p_declaration,p_attack_target,public.combat_v2_sha256(p_native),(c->>'turn_id')::uuid);
  RETURN 'applied';
END
